<?php
require_once __DIR__.'/core.php';require_once __DIR__.'/ad_lib.php';require_once __DIR__.'/federation_lib.php';require_once __DIR__.'/maintenance.php';tt_require_login();$user=(string)$_SESSION['name'];$id=(int)$_SESSION['id'];$db=tt_db_open(true);$adsReady=tt_ad_schema_ready($db);$hitsReady=tt_schema_table_exists($db,'post_impressions');try{tt_opportunistic_maintenance($db);tt_federation_tick($db);}catch(Throwable $e){}
$s=tt_prepare($db,'SELECT `aboutcontent`,`tags` FROM `accounts` WHERE `id`=?');$s->bind_param('i',$id);$s->execute();$s->bind_result($about,$myTags);$s->fetch();$s->close();
$stats=['posts'=>0,'impressions'=>0,'rated_posts'=>0,'top_moksha'=>0,'top_karma'=>0,'rep'=>0];$topHit=null;$topKarma=null;$topMoksha=null;$mokshaRows=[];
$s=tt_prepare($db,'SELECT COUNT(*) FROM `posts` WHERE `name`=?');$s->bind_param('s',$user);$s->execute();$s->bind_result($stats['posts']);$s->fetch();$s->close();$stats['posts']=(int)$stats['posts'];
if($hitsReady){$s=tt_prepare($db,'SELECT COUNT(*) FROM `post_impressions` pi JOIN `posts` p ON p.`id`=pi.`post_id` WHERE p.`name`=?');$s->bind_param('s',$user);$s->execute();$s->bind_result($stats['impressions']);$s->fetch();$s->close();$stats['impressions']=(int)$stats['impressions'];$s=tt_prepare($db,'SELECT p.`id`,p.`title`,COUNT(*) n FROM `post_impressions` pi JOIN `posts` p ON p.`id`=pi.`post_id` WHERE p.`name`=? GROUP BY p.`id`,p.`title` ORDER BY n DESC,p.`id` DESC LIMIT 1');$s->bind_param('s',$user);$s->execute();$topHit=$s->get_result()->fetch_assoc();$s->close();}
$rep=tt_account_reputation($db,$id);$stats['rep']=(int)($rep['slider']??0);$stats['rated_posts']=(int)($rep['ratings']??0);
// Creator rating is Moksha; external rating average is Karma. Keep them separately visible.
$s=tt_prepare($db,'SELECT p.`id`,p.`title`,pr.`perspective` FROM `posts` p LEFT JOIN `post_ratings` pr ON pr.`post_id`=p.`id` AND pr.`voter_account_id`=? WHERE p.`name`=? ORDER BY p.`dt` DESC,p.`id` DESC LIMIT 8');$s->bind_param('is',$id,$user);$s->execute();$mokshaRows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();foreach($mokshaRows as $m){$v=(int)($m['perspective']??0);if($topMoksha===null||$v>(int)$topMoksha['perspective'])$topMoksha=['id'=>(int)$m['id'],'title'=>(string)$m['title'],'perspective'=>$v];}$stats['top_moksha']=$topMoksha?(int)$topMoksha['perspective']:0;
$kq='SELECT p.`id`,p.`title`,ROUND(AVG(pr.`perspective`)) karma,COUNT(*) ratings FROM `posts` p JOIN `accounts` a ON a.`username`=p.`name` JOIN `post_ratings` pr ON pr.`post_id`=p.`id` AND pr.`voter_account_id`<>a.`id` WHERE a.`id`=? GROUP BY p.`id`,p.`title` ORDER BY karma DESC,ratings DESC,p.`id` DESC LIMIT 1';$s=tt_prepare($db,$kq);$s->bind_param('i',$id);$s->execute();$topKarma=$s->get_result()->fetch_assoc();$s->close();$stats['top_karma']=$topKarma?(int)$topKarma['karma']:0;
$ads=[];if($adsReady){$tagTokens=array_values(array_filter(array_map('trim',preg_split('/[;,]+/',(string)$myTags)?:[])));$adSql="SELECT p.`id`,p.`title`,p.`content`,p.`file`,p.`type`,pa.`mime_type` AS attachment_mime,ab.`id` AS boost_id FROM `ad_boosts` ab JOIN `posts` p ON p.`id`=ab.`post_id` LEFT JOIN `post_attachments` pa ON pa.`post_id`=p.`id` WHERE ab.`status`='active' AND ab.`budget_mills`>ab.`spent_mills` AND (ab.`target_username`=? OR ab.`target_username`=''";$ap=[$user];$at='s';if($tagTokens){$likes=[];foreach(array_slice($tagTokens,0,8) as $t){$likes[]='ab.`target_tags` LIKE ?';$ap[]='%'.$t.'%';$at.='s';}$adSql.=' OR '.implode(' OR ',$likes);}$adSql.=') ORDER BY (ab.`target_username`=?) DESC,(ab.`budget_mills`-ab.`spent_mills`) DESC LIMIT 8';$ap[]=$user;$at.='s';$x=tt_prepare($db,$adSql);$x->bind_param($at,...$ap);$x->execute();$ads=$x->get_result()->fetch_all(MYSQLI_ASSOC);$x->close();}
[$vis,$params,$types]=tt_visible_where('p');$sql='SELECT p.`id`,p.`title`,p.`content`,p.`dt`,p.`tags`,p.`name`,p.`scope`,p.`type`,p.`file` FROM `posts` p WHERE '.$vis.' ORDER BY p.`dt` DESC,p.`id` DESC LIMIT 30';$s=tt_prepare($db,$sql);$s->bind_param($types,...$params);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$db->close();
function tt_signed_stat($v):string{$v=(int)$v;return ($v>=0?'+':'').$v;}
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Home</title></head><body><?php tt_nav('home.php');?><main class="content"><section class="card"><h2><?=tt_h($user)?>'s timetable</h2><p><?=trim((string)$about)!==''?nl2br(tt_h($about)):'Your dashboard is ready. Create a post, message, group, event or forum.'?></p><div class="actions"><a href="create.php">Create</a><a href="post.php">Search posts</a><a href="profile.php">People</a><a href="friend.php">Friends</a><a href="statsmap.php">Stats</a></div></section>
<h2>Your stats</h2><section class="grid user-stats"><article class="card"><h3>Posts</h3><p class="stat-number"><?=number_format($stats['posts'])?></p></article><article class="card"><h3>Post impressions / hits</h3><p class="stat-number"><?=$hitsReady?number_format($stats['impressions']):'—'?></p><p class="meta"><?=$hitsReady?($topHit?'Top: #'.(int)$topHit['id'].' · '.tt_h($topHit['title']).' · '.number_format((int)$topHit['n']).' hits':'No counted hits yet.'):'Run the protected schema maintenance once to enable hit tracking.'?></p></article><article class="card"><h3>Top Moksha</h3><p class="stat-number"><?=tt_signed_stat($stats['top_moksha'])?> / 256</p><p class="meta"><?=$topMoksha?'Your creator perspective on #'.(int)$topMoksha['id'].' · '.tt_h($topMoksha['title']):'No creator perspectives yet.'?></p></article><article class="card"><h3>Top Karma</h3><p class="stat-number"><?=tt_signed_stat($stats['top_karma'])?> / 256</p><p class="meta"><?=$topKarma?'External average on #'.(int)$topKarma['id'].' · '.tt_h($topKarma['title']).' · '.(int)$topKarma['ratings'].' rating'.((int)$topKarma['ratings']===1?'':'s'):'No external ratings yet.'?></p></article><article class="card"><h3>Overall Karma/Moksha</h3><p class="stat-number"><?=tt_signed_stat($stats['rep'])?> / 256</p><p class="meta"><?=number_format($stats['rated_posts'])?> recorded rating<?=($stats['rated_posts']===1?'':'s')?> across your posts.</p></article></section>
<h2>Edit your Moksha values</h2><section class="grid"><?php foreach($mokshaRows as $m):$mv=(int)($m['perspective']??0);?><article class="card"><h3><a href="post.php#post-<?=(int)$m['id']?>">#<?=(int)$m['id']?> · <?=tt_h($m['title'])?></a></h3><form method="post" action="rate.php" class="rating-form"><input type="hidden" name="post_id" value="<?=(int)$m['id']?>"><label for="home-moksha-<?=(int)$m['id']?>">Moksha / creator perspective: <output id="home-moksha-out-<?=(int)$m['id']?>"><?=$mv?></output></label><input class="karma-slider" id="home-moksha-<?=(int)$m['id']?>" type="range" name="perspective" min="-256" max="256" step="1" value="<?=$mv?>" oninput="document.getElementById('home-moksha-out-<?=(int)$m['id']?>').value=this.value"><div class="slider-labels"><span>−256</span><span>0</span><span>+256</span></div><button type="submit">Save Moksha</button></form></article><?php endforeach;?><?php if(!$mokshaRows):?><article class="card"><p>Create a post to set its Moksha creator perspective.</p></article><?php endif;?></section>
<?php if($ads):?><h2>Sponsored / boosted for your page</h2><section class="grid ad-grid"><?php foreach($ads as $a):?><article class="card ad-card" data-boost-id="<?=(int)$a['boost_id']?>" data-page-owner-id="<?=$id?>"><p class="meta">Sponsored · natural credit exchange: 1 credit = 1 counted impression</p><h3><a href="post.php#post-<?=(int)$a['id']?>"><?=tt_h($a['title'])?></a></h3><p><?=nl2br(tt_h($a['content']))?></p><?=tt_ad_attachment_html($a)?></article><?php endforeach;?></section><?php endif;?><h2>Latest relevant posts</h2><section class="grid"><?php foreach($rows as $r):?><article class="card post-card" data-post-expandable="1" data-post-impression-id="<?=(int)$r['id']?>" aria-expanded="false"><h3><a href="post.php#post-<?=(int)$r['id']?>"><?=tt_h($r['title'])?></a></h3><p class="meta"><?=tt_h($r['name'])?> · <?=tt_h($r['dt'])?> · <?=tt_h(trim($r['scope']))?> · <?=tt_h($r['type'])?></p><p><?=nl2br(tt_h(mb_strimwidth((string)$r['content'],0,600,'…','UTF-8')))?></p><?php if($r['file']!==''):?><p><a href="<?=tt_h($r['file'])?>">Attachment</a></p><?php endif;?></article><?php endforeach;?><?php if(!$rows):?><article class="card"><p>No visible posts yet. <a href="create.php">Create the first one.</a></p></article><?php endif;?></section></main><script>document.querySelectorAll('[data-boost-id]').forEach(el=>{const f=new FormData();f.set('boost_id',el.dataset.boostId);f.set('page_owner_id',el.dataset.pageOwnerId||'0');fetch('ad_impression.php',{method:'POST',body:f,credentials:'same-origin',keepalive:true}).catch(()=>{});});document.querySelectorAll('[data-post-impression-id]').forEach(el=>{const f=new FormData();f.set('post_id',el.dataset.postImpressionId);fetch('post_impression.php',{method:'POST',body:f,credentials:'same-origin',keepalive:true}).catch(()=>{});});</script></body></html>